/**
 * AlarmManager.js — SNLS namespace
 *
 * Manages a local alarm list derived from REST equipment data.
 * Alarms are generated by inspecting equipment properties on every
 * poll cycle and de-duplicated within a 30-second window.
 *
 * API:
 *   SNLS.AlarmManager.processEquipmentAlarms(equipList, floorKey)
 *   SNLS.AlarmManager.getAlarms()          — full list (newest first)
 *   SNLS.AlarmManager.getActiveAlarms()    — unacknowledged only
 *   SNLS.AlarmManager.acknowledgeAlarm(id) — mark one alarm ACK
 *   SNLS.AlarmManager.renderAlarmTable()   — refresh #alarms-tbody
 *   SNLS.AlarmManager.setFilter(filter)    — 'all'|'critical'|'warning'|'active'
 *
 * Globals exposed for inline onclick handlers:
 *   window.SNLS.setAlarmFilter(filter)
 *   window.SNLS.ackAlarm(id)
 *
 * ES5 STRICT — no let/const, no arrow functions, no template literals.
 */
(function(window) {
  'use strict';

  var SNLS = window.SNLS || {};

  // ---------------------------------------------------------------------------
  // Private state
  // ---------------------------------------------------------------------------

  var _alarms      = [];
  var _alarmFilter = 'all';
  var _nextId      = 1;

  // Maximum alarms kept in memory. Oldest are dropped from the tail.
  var MAX_ALARMS = 200;
  // Deduplication window in milliseconds.
  var DEDUP_MS = 30000;
  // Maximum rows rendered in the table at once.
  var MAX_RENDER = 50;

  // ---------------------------------------------------------------------------
  // Alarm rules — each rule is { test(equip), message(equip), severity }
  // test returns true when the condition is active.
  // ---------------------------------------------------------------------------

  var RULES = [
    {
      test: function(e) { return !e.online; },
      message: function() { return 'Fallo de comunicacion'; },
      severity: 'critical'
    }
  ];

  // ---------------------------------------------------------------------------
  // _addAlarm — internal, deduplicated insert
  // ---------------------------------------------------------------------------

  function _addAlarm(equip, message, severity, floorKey) {
    var name = equip.equipName || equip.tag || 'RTU';
    var now  = Date.now();

    for (var i = 0; i < _alarms.length; i++) {
      var a = _alarms[i];
      if (a.equipName === name &&
          a.message   === message &&
          (now - a.time.getTime()) < DEDUP_MS) {
        return;
      }
    }

    _alarms.unshift({
      id           : _nextId++,
      equipName    : name,
      floor        : floorKey || '',
      message      : message,
      severity     : severity,
      time         : new Date(now),
      acknowledged : false
    });

    if (_alarms.length > MAX_ALARMS) {
      _alarms.pop();
    }
  }

  // ---------------------------------------------------------------------------
  // processEquipmentAlarms — called by DashboardApp on each REST poll
  // ---------------------------------------------------------------------------

  function processEquipmentAlarms(equipList, floorKey) {
    if (!equipList || !equipList.length) {
      return;
    }

    for (var i = 0; i < equipList.length; i++) {
      var equip = equipList[i];
      for (var r = 0; r < RULES.length; r++) {
        var rule = RULES[r];
        if (rule.test(equip)) {
          _addAlarm(equip, rule.message(equip), rule.severity, floorKey);
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // Query helpers
  // ---------------------------------------------------------------------------

  function getAlarms() {
    return _alarms;
  }

  function getActiveAlarms() {
    var result = [];
    for (var i = 0; i < _alarms.length; i++) {
      if (!_alarms[i].acknowledged) {
        result.push(_alarms[i]);
      }
    }
    return result;
  }

  // ---------------------------------------------------------------------------
  // acknowledgeAlarm(id)
  // ---------------------------------------------------------------------------

  function acknowledgeAlarm(id) {
    for (var i = 0; i < _alarms.length; i++) {
      if (_alarms[i].id === id) {
        _alarms[i].acknowledged = true;
        break;
      }
    }
    renderAlarmTable();
  }

  // ---------------------------------------------------------------------------
  // _buildCounts — compute filter badge counts
  // ---------------------------------------------------------------------------

  function _buildCounts() {
    var all    = _alarms.length;
    var crit   = 0;
    var warn   = 0;
    var active = 0;
    for (var k = 0; k < _alarms.length; k++) {
      if (_alarms[k].severity === 'critical')   { crit++; }
      if (_alarms[k].severity === 'warning')    { warn++; }
      if (!_alarms[k].acknowledged)             { active++; }
    }
    return { all: all, critical: crit, warning: warn, active: active };
  }

  // ---------------------------------------------------------------------------
  // _updateBadgeElement — safe null-checked text update
  // ---------------------------------------------------------------------------

  function _updateBadgeElement(id, value) {
    var el = document.getElementById(id);
    if (el) {
      el.textContent = value;
    }
  }

  // ---------------------------------------------------------------------------
  // _buildSeverityLabel
  // ---------------------------------------------------------------------------

  function _buildSeverityLabel(severity) {
    if (severity === 'critical') {
      return '<span class="alarm-severity critical"></span>Critica';
    }
    return '<span class="alarm-severity warning"></span>Advertencia';
  }

  // ---------------------------------------------------------------------------
  // renderAlarmTable — updates #alarms-tbody and filter badge counts
  // ---------------------------------------------------------------------------

  function renderAlarmTable() {
    var ic = (SNLS.Icons && SNLS.Icons.get)
      ? SNLS.Icons.get
      : function() { return ''; };

    // --- apply filter ---
    var filtered = [];
    var i;

    if (_alarmFilter === 'critical') {
      for (i = 0; i < _alarms.length; i++) {
        if (_alarms[i].severity === 'critical') {
          filtered.push(_alarms[i]);
        }
      }
    } else if (_alarmFilter === 'warning') {
      for (i = 0; i < _alarms.length; i++) {
        if (_alarms[i].severity === 'warning') {
          filtered.push(_alarms[i]);
        }
      }
    } else if (_alarmFilter === 'active') {
      filtered = getActiveAlarms();
    } else {
      for (i = 0; i < _alarms.length; i++) {
        filtered.push(_alarms[i]);
      }
    }

    // --- render tbody ---
    var tbody = document.getElementById('alarms-tbody');
    if (tbody) {
      if (filtered.length === 0) {
        tbody.innerHTML =
          '<tr><td colspan="6">' +
            '<div class="empty-state-enhanced">' +
              ic('shieldCheck', 48) +
              '<p>No hay alarmas' +
                (_alarmFilter !== 'all' ? ' con este filtro' : ' registradas') +
              '</p>' +
            '</div>' +
          '</td></tr>';
      } else {
        var html = '';
        var max  = Math.min(filtered.length, MAX_RENDER);
        for (var j = 0; j < max; j++) {
          var a        = filtered[j];
          var rowClass = a.acknowledged ? ' class="alarm-row-ack"' : '';
          var timeStr  = a.time.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
          var ackCell;

          if (a.acknowledged) {
            ackCell = '<span class="badge badge-info">' + ic('check', 12) + ' ACK</span>';
          } else {
            ackCell = '<button class="alarm-ack-btn" onclick="window.SNLS.ackAlarm(' + a.id + ')">' +
                        ic('check', 12) + ' Reconocer' +
                      '</button>';
          }

          html +=
            '<tr' + rowClass + '>' +
              '<td>' + _buildSeverityLabel(a.severity) + '</td>' +
              '<td><strong>' + a.equipName + '</strong></td>' +
              '<td>' + a.floor + '</td>' +
              '<td>' + a.message + '</td>' +
              '<td class="mono text-sm">' + timeStr + '</td>' +
              '<td>' + ackCell + '</td>' +
            '</tr>';
        }
        tbody.innerHTML = html;
      }
    }

    // --- update nav alarm badge ---
    var active = getActiveAlarms();
    var navBadge = document.getElementById('nav-alarm-badge');
    if (navBadge) {
      if (active.length > 0) {
        navBadge.textContent = active.length;
        navBadge.style.display = '';
      } else {
        navBadge.style.display = 'none';
      }
    }

    // --- update filter counts ---
    var counts = _buildCounts();
    _updateBadgeElement('alarm-count-all',      counts.all);
    _updateBadgeElement('alarm-count-critical', counts.critical);
    _updateBadgeElement('alarm-count-warning',  counts.warning);
    _updateBadgeElement('alarm-count-active',   counts.active);
  }

  // ---------------------------------------------------------------------------
  // setFilter — update _alarmFilter and re-render
  // ---------------------------------------------------------------------------

  function setFilter(filter) {
    _alarmFilter = filter;

    var btns = document.querySelectorAll('.alarm-filter-btn');
    for (var i = 0; i < btns.length; i++) {
      if (btns[i].getAttribute('data-filter') === filter) {
        btns[i].classList.add('active');
      } else {
        btns[i].classList.remove('active');
      }
    }

    renderAlarmTable();
  }

  // ---------------------------------------------------------------------------
  // Expose inline onclick globals
  // ---------------------------------------------------------------------------

  window.SNLS = window.SNLS || {};
  window.SNLS.setAlarmFilter = setFilter;
  window.SNLS.ackAlarm       = acknowledgeAlarm;

  // ---------------------------------------------------------------------------
  // Public API
  // ---------------------------------------------------------------------------

  SNLS.AlarmManager = {
    processEquipmentAlarms : processEquipmentAlarms,
    getAlarms              : getAlarms,
    getActiveAlarms        : getActiveAlarms,
    acknowledgeAlarm       : acknowledgeAlarm,
    renderAlarmTable       : renderAlarmTable,
    setFilter              : setFilter
  };

  window.SNLS = SNLS;

})(window);
